def handle(args, state, ds):
    report = ds.consistency_report()
    if report["pending"] == 0:
        return {"status": "complete", "remaining": 0}
    return {"status": "in_progress", "remaining": report["pending"]}

def handle(args, state, ds):
    report = ds.sync_status()
    if report["drift"]:
        return {"status": "syncing", "detail": report}
    return {"status": "synced", "detail": report}

